messages.content:
Tool response:
Tool: send_ethereum_transaction
Description: Send Ethereum Transaction
Parameters:
    {
      "type": "object",
      "properties": {
        "wallet_id": {
          "type": "integer",
          "title": "Wallet Id",
          "description": "Internal ID of the sending wallet"
        },
        "recipient_address": {
          "type": "string",
          "title": "Recipient Address",
          "description": "External Ethereum address to send funds to"
        },
        "amount": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Amount",
          "description": "Amount of ETH to send"
        },
        "note": {
          "type": "string",
          "title": "Note",
          "description": "Note to attach to the transaction"
        }
      },
      "required": [
        "wallet_id",
        "recipient_address",
        "amount",
        "note"
      ]
    }
